def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_def = 0
    for a, b in history:
        if b == 'D':
            opp_def += 1
    if opp_def == 0:
        return 'C'
    forgive_failed = False
    for i in range(n - 1):
        if history[i] == ('C', 'D') and history[i+1] == ('C', 'D'):
            forgive_failed = True
            break
    if n >= 2:
        last = history[-1]
        prev = history[-2]
        if (last == ('C', 'D') and prev == ('D', 'C')) or (last == ('D', 'C') and prev == ('C', 'D')):
            return 'C'
    if not forgive_failed:
        if n >= 3:
            last3 = history[-3:]
            if all(a == 'D' and b == 'D' for a, b in last3):
                return 'C'
        if n >= 4 and history[-1] == ('C', 'D'):
            ok = True
            for i in range(n - 4, n - 1):
                if history[i][0] != 'D' or history[i][1] != 'D':
                    ok = False
                    break
            if ok:
                return 'C'
        if n >= 10 and opp_def <= 2 and history[-1][1] == 'D':
            if n < 2 or history[-2][1] == 'C':
                return 'C'
    if history[-1][1] == 'D':
        return 'D'
    return 'C'
